import{_ as a,o as n,c as e,O as l}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"面试手撕现场","description":"手写代码环节怎么表现：读题确认、说思路、白板写法、卡住怎么办、边界自查清单，以及面试官最常追问的四个方向。","frontmatter":{"description":"手写代码环节怎么表现：读题确认、说思路、白板写法、卡住怎么办、边界自查清单，以及面试官最常追问的四个方向。","tags":["算法","并发编程"]},"headers":[],"relativePath":"algorithm/面试手撕现场.md","filePath":"algorithm/面试手撕现场.md","lastUpdated":1793245104000}'),t={name:"algorithm/面试手撕现场.md"};function o(p,s,r,c,i,d){return n(),e("div",null,s[0]||(s[0]=[l(`<h1 id="面试手撕现场" tabindex="-1">面试手撕现场 <a class="header-anchor" href="#面试手撕现场" aria-label="Permalink to &quot;面试手撕现场&quot;">​</a></h1><blockquote><p>手写题考的不只是代码 —— 同一个答案，有的人拿「思路清晰、边界严谨」，有的人拿「写完了但不敢说话」。 这一页讲<strong>过程</strong>，代码模板在 <a href="./手写题清单">手写题清单</a>。</p></blockquote><h2 id="三个阶段的节奏" tabindex="-1">三个阶段的节奏 <a class="header-anchor" href="#三个阶段的节奏" aria-label="Permalink to &quot;三个阶段的节奏&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">0–1 分钟   读题 + 确认（别急着写）</span></span>
<span class="line"><span style="color:#e1e4e8;">1–3 分钟   说思路 + 复杂度（面试官点头再动手）</span></span>
<span class="line"><span style="color:#e1e4e8;">3–12 分钟  写代码（边写边讲）</span></span>
<span class="line"><span style="color:#e1e4e8;">12–15 分钟 自查边界 + 手跑一个例子</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">0–1 分钟   读题 + 确认（别急着写）</span></span>
<span class="line"><span style="color:#24292e;">1–3 分钟   说思路 + 复杂度（面试官点头再动手）</span></span>
<span class="line"><span style="color:#24292e;">3–12 分钟  写代码（边写边讲）</span></span>
<span class="line"><span style="color:#24292e;">12–15 分钟 自查边界 + 手跑一个例子</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>最忌讳</strong>：一言不发直接写，写了 10 分钟发现方向错了。</p><h2 id="一、读题与确认-0–1-分钟" tabindex="-1">一、读题与确认（0–1 分钟） <a class="header-anchor" href="#一、读题与确认-0–1-分钟" aria-label="Permalink to &quot;一、读题与确认（0–1 分钟）&quot;">​</a></h2><p>把题复述一遍，然后问三个问题：</p><table><thead><tr><th>问什么</th><th>为什么问</th></tr></thead><tbody><tr><td>「输入规模大概多大？」</td><td>决定能不能 O(n²)，要不要用哈希/堆</td></tr><tr><td>「有没有重复元素 / 负数 / 空输入？」</td><td>直接决定边界处理</td></tr><tr><td>「返回下标还是返回值？可以修改原数组吗？」</td><td>这两点搞错，代码白写</td></tr></tbody></table><p>复述模板：</p><blockquote><p>「我理解一下：给一个有序数组和一个 target，返回两个数的下标，保证有且只有一个答案，对吗？数组长度大概多少？可以有重复值吗？」</p></blockquote><h2 id="二、说思路-1–3-分钟" tabindex="-1">二、说思路（1–3 分钟） <a class="header-anchor" href="#二、说思路-1–3-分钟" aria-label="Permalink to &quot;二、说思路（1–3 分钟）&quot;">​</a></h2><p><strong>先给一句结论，再展开</strong>：</p><blockquote><p>「这题我用双指针，因为数组有序。左指针从头、右指针从尾，和大于 target 就右指针左移，小于就左指针右移。时间 O(n)，空间 O(1)。」</p></blockquote><p>三句话结构：<strong>用什么方法 → 为什么（利用了题目什么性质）→ 复杂度</strong>。</p><p>如果想到两个方案，主动比较：</p><blockquote><p>「暴力是 O(n²)，用哈希表可以降到 O(n) 但要多 O(n) 空间。我倾向哈希，除非你希望空间 O(1)。」</p></blockquote><h2 id="三、写代码-3–12-分钟" tabindex="-1">三、写代码（3–12 分钟） <a class="header-anchor" href="#三、写代码-3–12-分钟" aria-label="Permalink to &quot;三、写代码（3–12 分钟）&quot;">​</a></h2><h3 id="先写骨架" tabindex="-1">先写骨架 <a class="header-anchor" href="#先写骨架" aria-label="Permalink to &quot;先写骨架&quot;">​</a></h3><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#F97583;">public</span><span style="color:#E1E4E8;"> </span><span style="color:#F97583;">int</span><span style="color:#E1E4E8;">[] </span><span style="color:#B392F0;">twoSum</span><span style="color:#E1E4E8;">(</span><span style="color:#F97583;">int</span><span style="color:#E1E4E8;">[] nums, </span><span style="color:#F97583;">int</span><span style="color:#E1E4E8;"> target) {</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#6A737D;">// 1. 边界</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#6A737D;">// 2. 主逻辑</span></span>
<span class="line"><span style="color:#E1E4E8;">    </span><span style="color:#6A737D;">// 3. 返回</span></span>
<span class="line"><span style="color:#E1E4E8;">}</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#D73A49;">public</span><span style="color:#24292E;"> </span><span style="color:#D73A49;">int</span><span style="color:#24292E;">[] </span><span style="color:#6F42C1;">twoSum</span><span style="color:#24292E;">(</span><span style="color:#D73A49;">int</span><span style="color:#24292E;">[] nums, </span><span style="color:#D73A49;">int</span><span style="color:#24292E;"> target) {</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#6A737D;">// 1. 边界</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#6A737D;">// 2. 主逻辑</span></span>
<span class="line"><span style="color:#24292E;">    </span><span style="color:#6A737D;">// 3. 返回</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>把注释写上，再填内容 —— 面试官能看出你的结构感。</p><h3 id="边写边说" tabindex="-1">边写边说 <a class="header-anchor" href="#边写边说" aria-label="Permalink to &quot;边写边说&quot;">​</a></h3><p>不需要解说每一行，但要在<strong>关键决策处出声</strong>：</p><ul><li>「这里我用 <code>long</code> 防止溢出」</li><li>「这里先判空，否则下面会 NPE」</li><li>「这个变量我叫 <code>prev</code> / <code>cur</code>，方便对照」</li></ul><h3 id="命名与格式" tabindex="-1">命名与格式 <a class="header-anchor" href="#命名与格式" aria-label="Permalink to &quot;命名与格式&quot;">​</a></h3><ul><li>用有意义的名字：<code>left/right</code>、<code>slow/fast</code>、<code>prev/cur</code></li><li>别写一行 200 字符，该换行就换行</li><li>循环里别做重复计算（<code>a.length</code> 提到外面）</li></ul><h2 id="四、卡住了怎么办" tabindex="-1">四、卡住了怎么办 <a class="header-anchor" href="#四、卡住了怎么办" aria-label="Permalink to &quot;四、卡住了怎么办&quot;">​</a></h2><table><thead><tr><th>卡在哪</th><th>说什么 / 做什么</th></tr></thead><tbody><tr><td>没思路</td><td>「我先写一个暴力解，再看能不能优化」—— 暴力解也是分</td></tr><tr><td>边界想不清</td><td>举一个最小例子，手动走一遍</td></tr><tr><td>写到一半发现错了</td><td>直接说「我这里逻辑有问题，我换个思路」，不要硬改</td></tr><tr><td>忘了 API 名</td><td>「这个方法我记不清名字，假设它叫 <code>findFirst</code>，作用是……」</td></tr></tbody></table><p><strong>主动示弱比沉默好</strong>：面试官愿意给提示，但你不说话他就没法给。</p><h2 id="五、写完必须自查-12–15-分钟" tabindex="-1">五、写完必须自查（12–15 分钟） <a class="header-anchor" href="#五、写完必须自查-12–15-分钟" aria-label="Permalink to &quot;五、写完必须自查（12–15 分钟）&quot;">​</a></h2><p>按顺序过一遍，<strong>出声</strong>：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">「我先检查一下边界：</span></span>
<span class="line"><span style="color:#e1e4e8;"> 空数组 —— 我这里有 length 判断，返回 -1，OK。</span></span>
<span class="line"><span style="color:#e1e4e8;"> 单元素 —— 循环进不去，返回 -1，OK。</span></span>
<span class="line"><span style="color:#e1e4e8;"> 全相同元素 —— 我用的是 &gt;=，会跳过，OK。</span></span>
<span class="line"><span style="color:#e1e4e8;"> 然后手跑一个例子：nums=[2,7,11,15], target=9</span></span>
<span class="line"><span style="color:#e1e4e8;"> l=0,r=3: 2+15=17 &gt; 9，r-- → r=2</span></span>
<span class="line"><span style="color:#e1e4e8;"> l=0,r=2: 2+11=13 &gt; 9，r-- → r=1</span></span>
<span class="line"><span style="color:#e1e4e8;"> l=0,r=1: 2+7=9，返回 [0,1]，对了。」</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">「我先检查一下边界：</span></span>
<span class="line"><span style="color:#24292e;"> 空数组 —— 我这里有 length 判断，返回 -1，OK。</span></span>
<span class="line"><span style="color:#24292e;"> 单元素 —— 循环进不去，返回 -1，OK。</span></span>
<span class="line"><span style="color:#24292e;"> 全相同元素 —— 我用的是 &gt;=，会跳过，OK。</span></span>
<span class="line"><span style="color:#24292e;"> 然后手跑一个例子：nums=[2,7,11,15], target=9</span></span>
<span class="line"><span style="color:#24292e;"> l=0,r=3: 2+15=17 &gt; 9，r-- → r=2</span></span>
<span class="line"><span style="color:#24292e;"> l=0,r=2: 2+11=13 &gt; 9，r-- → r=1</span></span>
<span class="line"><span style="color:#24292e;"> l=0,r=1: 2+7=9，返回 [0,1]，对了。」</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这一段是<strong>加分最多的地方</strong>，很多人写完就停，白白丢掉。</p><h2 id="六、常见追问-准备这四个方向" tabindex="-1">六、常见追问（准备这四个方向） <a class="header-anchor" href="#六、常见追问-准备这四个方向" aria-label="Permalink to &quot;六、常见追问（准备这四个方向）&quot;">​</a></h2><table><thead><tr><th>追问</th><th>准备什么</th></tr></thead><tbody><tr><td><strong>能不能优化时间/空间？</strong></td><td>每道题想一个「次优解」：哈希换时间、双指针省空间</td></tr><tr><td><strong>数据量变大到 1 亿怎么办？</strong></td><td>外部排序 / 分治 / 布隆过滤器 / 只存 TopK</td></tr><tr><td><strong>并发场景怎么改？</strong></td><td>加锁粒度、无锁 CAS、分段（参考 <a href="/cao_note/backend/Java/06-JUC并发编程">JUC 并发编程</a>）</td></tr><tr><td><strong>异常输入怎么办？</strong></td><td>参数校验、快速失败、返回明确错误</td></tr></tbody></table><h2 id="七、几个真实的坑" tabindex="-1">七、几个真实的坑 <a class="header-anchor" href="#七、几个真实的坑" aria-label="Permalink to &quot;七、几个真实的坑&quot;">​</a></h2><ul><li><strong>不要用 IDE 的自动补全</strong>（共享编辑器里可能没有）；写 <code>fori</code> 循环时手写完整。</li><li><strong>不要在纸上写省略号</strong>（<code>...</code>），面试官会以为你没想清楚。</li><li><strong>不要提前说「这题我做过」</strong>，除非你能立刻写出并解释；说了却卡住更扣分。</li><li><strong>时间到了没写完</strong>：主动说「剩下的部分是 XX，我口述一下」—— 比沉默收尾好。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p>手撕题的评分表通常是：<strong>边界 30% + 思路 30% + 代码正确 30% + 沟通 10%</strong>。 也就是说，代码没一次写对，只要边界和思路清楚，仍然能过。</p></blockquote>`,38)]))}const u=a(t,[["render",o]]);export{b as __pageData,u as default};
